sealed class Outcome8962 {
    data class Success(val payload: String) : Outcome8962()
    data object Failure : Outcome8962()
}

fun describe8962(outcome: Outcome8962): String = when (outcome) {
    is Outcome8962.Success -> outcome.payload
    Outcome8962.Failure -> "failed"
}
